import java.io.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.*;
import java.security.*;
import java.nio.charset.StandardCharsets;
import javax.crypto.*;
import javax.crypto.spec.*;

public class ChatServer {
    private static final int PORT = 8443;
    private static final int POOL_SIZE = 32;
    private static final Map<String, UserSession> activeSessions = new ConcurrentHashMap<>();
    private static final ExecutorService connectionPool = Executors.newFixedThreadPool(POOL_SIZE);
    private static final Map<String, String> userTokens = new ConcurrentHashMap<>();
    private static final byte[] HMAC_KEY = loadHmacKey();

    static {
        loadUserTokens();
    }

    /**
     * Load the HMAC key from a secure external source instead of hardcoding it.
     * Set CHAT_HMAC_KEY in the environment (or provide via a secrets manager).
     */
    private static byte[] loadHmacKey() {
        String key = System.getenv("CHAT_HMAC_KEY");
        if (key == null || key.isEmpty()) {
            key = System.getProperty("chat.hmac.key");
        }
        if (key == null || key.isEmpty()) {
            throw new IllegalStateException(
                "HMAC key not configured. Set CHAT_HMAC_KEY environment variable or chat.hmac.key system property.");
        }
        return key.getBytes(StandardCharsets.UTF_8);
    }

    /**
     * Load user tokens from a secure external source instead of hardcoding them.
     * Expected format in CHAT_USER_TOKENS or chat.user.tokens: "user1:token1,user2:token2".
     */
    private static void loadUserTokens() {
        String raw = System.getenv("CHAT_USER_TOKENS");
        if (raw == null || raw.isEmpty()) {
            raw = System.getProperty("chat.user.tokens");
        }
        if (raw == null || raw.isEmpty()) {
            throw new IllegalStateException(
                "User tokens not configured. Set CHAT_USER_TOKENS environment variable or chat.user.tokens system property.");
        }
        for (String entry : raw.split(",")) {
            String[] kv = entry.split(":", 2);
            if (kv.length == 2) {
                String user = kv[0].trim();
                String token = kv[1].trim();
                if (!user.isEmpty() && !token.isEmpty()) {
                    userTokens.put(user, token);
                }
            }
        }
    }

    public static void main(String[] args) throws IOException {
        ServerSocket serverSocket = new ServerSocket(PORT);
        System.out.println("Chat server started on port " + PORT);
        while (true) {
            Socket client = serverSocket.accept();
            connectionPool.submit(new ClientHandler(client));
        }
    }

    static class UserSession {
        final String username;
        final long createdAt;
        final Socket socket;
        volatile boolean authenticated;

        UserSession(String username, Socket socket) {
            this.username = username;
            this.createdAt = System.nanoTime();
            this.socket = socket;
            this.authenticated = false;
        }
    }

    static class ClientHandler implements Runnable {
        private final Socket socket;
        private BufferedReader in;
        private PrintWriter out;

        ClientHandler(Socket socket) {
            this.socket = socket;
        }

        @Override
        public void run() {
            try {
                socket.setSoTimeout(30000);
                in = new BufferedReader(new InputStreamReader(socket.getInputStream(), StandardCharsets.UTF_8));
                out = new PrintWriter(new OutputStreamWriter(socket.getOutputStream(), StandardCharsets.UTF_8), true);
                out.println("CHAT/1.0 READY");
                String authLine = in.readLine();
                if (authLine == null || !authLine.startsWith("AUTH ")) {
                    out.println("ERR PROTOCOL");
                    return;
                }
                String[] parts = authLine.substring(5).split(":", 2);
                if (parts.length != 2) {
                    out.println("ERR FORMAT");
                    return;
                }
                String username = parts[0].trim();
                String token = parts[1].trim();
                if (!authenticateUser(username, token)) {
                    out.println("ERR AUTH_FAILED");
                    return;
                }
                UserSession session = new UserSession(username, socket);
                session.authenticated = true;
                activeSessions.put(username, session);
                out.println("OK AUTHENTICATED");
                handleMessages(session);
            } catch (IOException e) {
                // Connection error
            } finally {
                try { socket.close(); } catch (IOException e) {}
            }
        }

        private boolean authenticateUser(String username, String providedToken) {
            String storedToken = userTokens.get(username);
            if (storedToken == null) {
                // Simulate work to avoid user enumeration via gross timing
                computeHmac("dummy-value");
                return false;
            }
            String expectedMac = computeHmac(storedToken);
            String providedMac = computeHmac(providedToken);
            return sequenceEqual(expectedMac, providedMac);
        }

        private boolean sequenceEqual(String a, String b) {
            if (a.length() != b.length()) return false;
            int result = 0;
            for (int i = 0; i < a.length(); i++) {
                result |= a.charAt(i) ^ b.charAt(i);
            }
            return result == 0;
        }

        private String computeHmac(String input) {
            try {
                Mac mac = Mac.getInstance("HmacSHA256");
                SecretKeySpec keySpec = new SecretKeySpec(HMAC_KEY, "HmacSHA256");
                mac.init(keySpec);
                byte[] rawHmac = mac.doFinal(input.getBytes(StandardCharsets.UTF_8));
                return bytesToHex(rawHmac);
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        }

        private String bytesToHex(byte[] bytes) {
            StringBuilder sb = new StringBuilder(bytes.length * 2);
            for (byte b : bytes) {
                sb.append(String.format("%02x", b & 0xff));
            }
            return sb.toString();
        }

        private void handleMessages(UserSession session) throws IOException {
            String line;
            while ((line = in.readLine()) != null) {
                if (line.startsWith("MSG ")) {
                    String[] msgParts = line.substring(4).split(" ", 2);
                    if (msgParts.length == 2) {
                        deliverMessage(session.username, msgParts[0], msgParts[1]);
                    }
                } else if (line.equals("LIST")) {
                    out.println("USERS " + String.join(",", activeSessions.keySet()));
                } else if (line.equals("QUIT")) {
                    activeSessions.remove(session.username);
                    out.println("BYE");
                    break;
                } else if (line.startsWith("PRIVMSG ")) {
                    handlePrivateMessage(session, line.substring(8));
                }
            }
        }

        private void handlePrivateMessage(UserSession sender, String payload) {
            String[] parts = payload.split(" ", 3);
            if (parts.length < 3) {
                out.println("ERR PRIVMSG_FORMAT");
                return;
            }
            String recipient = parts[0];
            String msgToken = parts[1];
            String message = parts[2];
            UserSession recipientSession = activeSessions.get(recipient);
            if (recipientSession == null) {
                out.println("ERR USER_OFFLINE");
                return;
            }
            // Verify message authentication token
            String expectedToken = userTokens.get(sender.username);
            if (expectedToken != null && verifyMessageToken(expectedToken, msgToken)) {
                deliverMessage(sender.username, recipient, "[PRIVATE] " + message);
                out.println("OK DELIVERED");
            } else {
                out.println("ERR INVALID_TOKEN");
            }
        }

        private boolean verifyMessageToken(String expected, String provided) {
            if (expected.length() != provided.length()) return false;
            int result = 0;
            for (int i = 0; i < expected.length(); i++) {
                result |= expected.charAt(i) ^ provided.charAt(i);
            }
            return result == 0;
        }

        private void deliverMessage(String from, String to, String message) {
            UserSession recipient = activeSessions.get(to);
            if (recipient != null && recipient.authenticated) {
                try {
                    PrintWriter recipientOut = new PrintWriter(
                        new OutputStreamWriter(recipient.socket.getOutputStream(), StandardCharsets.UTF_8), true);
                    recipientOut.println("FROM " + from + " " + message);
                } catch (IOException e) {
                    activeSessions.remove(to);
                }
            }
        }
    }
}
